style.css:
/* Canva Dark Fantasy - canva.com */
:root {
  /* troque as cores aqui à vontade */
  --my-bg: #0d0a12;
  --my-text: #d8cfc0;
  --my-accent: #8b1e2d;
  --my-gold: #b8964e;
  --my-selection: #4a1520;
}

/* fundo escuro e texto de pergaminho */
html,
body {
  background-color: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* títulos com ar de grimório */
h1, h2, h3 {
  color: var(--my-gold) !important;
  font-family: Georgia, "Palatino Linotype", serif !important;
  letter-spacing: 0.03em !important;
}

/* links em vermelho-sangue */
a {
  color: var(--my-accent) !important;
}
a:hover {
  color: var(--my-gold) !important;
}

/* cor da seleção de texto */
::selection {
  background: var(--my-selection) !important;
  color: #f2e8d5 !important;
}

/* barra de rolagem fina, dourado envelhecido */
html {
  scrollbar-width: thin !important;
  scrollbar-color: var(--my-gold) var(--my-bg) !important;
}

/* contorno de foco dourado */
a:focus-visible,
button:focus-visible {
  outline: 2px solid var(--my-gold) !important;
  outline-offset: 2px !important;
}

/* imagens com cantos arredondados */
img {
  border-radius: 6px !important;
}
